#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int cal(vector<int> a, int k, int n) {
    int l = 0, cnt = 0, res = 0;
    for (int r = 0; r < a.size(); r++) {
        if (r != 0) {
            cnt += a[r] - a[r - 1] - 1;
        }
        while (cnt > k) {
            cnt -= a[l + 1] - a[l] - 1;
            l += 1;
        }
        res = max(res, a[r] - a[l] + 1 + k - cnt);
    }
    return min(n, res);
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<int>> idx(m + 1);
    vector<int> v(n);

    for (int i = 0; i < n; i++) {
        cin >> v[i];
        idx[v[i]].push_back(i);
    }

    int ans = k;
    for (auto id : idx) {
        ans = max(ans, cal(id, k, n));
    }

    cout << ans << endl;

    return 0;
}
```
